const goodDesc = "A clear description.";
const two = ["First verifiable criterion", "Second verifiable criterion"];

test("the limits shown to people are the contract's", () => {
  assert.deepEqual(
    { ...LIMITS },
    { titleMax: 200, descriptionMax: 5000, criteriaMin: 1, criteriaMax: 20, criterionMax: 1000 },
  );
});

test("title is required and bounded at 200 characters", () => {
  assert.ok(validateTitle("   "));
  assert.equal(validateTitle("Logo files"), null);
  assert.equal(validateTitle("x".repeat(200)), null);
  assert.match(validateTitle("x".repeat(201))!, /at most 200/);
});

test("lengths count characters the way the contract does (code points, after stripping)", () => {
  assert.equal(validateTitle("😀".repeat(200)), null, "emoji count once, not twice");
  assert.ok(validateTitle("😀".repeat(201)));
  assert.equal(validateTitle("  " + "x".repeat(200) + "  "), null, "padding is stripped before counting");
  assert.match(validateTitle("x".repeat(205))!, /currently 205/);
});

test("description: required, up to 5000 characters, no minimum (the contract has none)", () => {
  assert.ok(validateDescription(""));
  assert.equal(validateDescription("Short"), null);
  assert.equal(validateDescription(goodDesc), null);
  assert.equal(validateDescription("x".repeat(5000)), null);
  assert.match(validateDescription("x".repeat(5001))!, /at most 5000/);
  assert.equal(validateDescription("Line one\n\tLine two"), null, "line breaks and tabs are allowed in descriptions");
  assert.ok(validateDescription("bad\x07bell"));
});

test("titles and criteria are single-line", () => {
  assert.ok(validateTitle("two\nlines"));
  assert.ok(validateCriteria(["fine one", "two\nlines"]).errors["criteria.1"]);
  assert.ok(validateTitle("nul\x00"));
  assert.ok(validateTitle("del\x7f"));
});

test("text that cannot be stored is refused instead of being altered on the way", () => {
  assert.ok(validateTitle("broken \ud800 surrogate"));
});

test("criteria count must be between 1 and 20", () => {
  const many = (n: number) => Array.from({ length: n }, (_, i) => `Criterion number ${i + 1}`);
  assert.ok(validateCriteria([]).errors.criteria);
  assert.equal(validateCriteria(["only one"]).ok, true, "the contract accepts a single criterion");
  assert.equal(validateCriteria(two).ok, true);
  assert.equal(validateCriteria(many(20)).ok, true);
  assert.ok(validateCriteria(many(21)).errors.criteria);
});

test("a criterion can be 1000 characters, not 1001", () => {
  assert.equal(validateCriteria(["x".repeat(1000), "y"]).ok, true);
  const r = validateCriteria(["Good criterion", "x".repeat(1001)]);
  assert.match(r.errors["criteria.1"]!, /at most 1000/);
});

test("empty, over-long and duplicate criteria are reported per row", () => {
  const r = validateCriteria(["Good criterion", "   ", "x".repeat(1001), "good   CRITERION"]);
  assert.equal(r.ok, false);
  assert.ok(r.errors["criteria.1"]);
  assert.ok(r.errors["criteria.2"]);
  assert.match(r.errors["criteria.3"]!, /repeats criterion 1/);
  assert.equal(r.errors["criteria.0"], undefined);
});

test("validateDraft merges every error", () => {
  const r = validateDraft("", "", []);
  assert.deepEqual(Object.keys(r.errors).sort(), ["criteria", "description", "title"]);
  assert.equal(validateDraft("Title", goodDesc, two).ok, true);
});

test("criterion ids are the contract's: C1..Cn by position, stripped text", () => {
  const c = buildCriteria(["  one  ", "two"]);
  assert.deepEqual(c, [{ id: "C1", text: "one" }, { id: "C2", text: "two" }]);
  assert.equal(hasValidCriterionIds(c), true);
  assert.equal(hasValidCriterionIds([{ id: "C1", text: "a" }, { id: "C1", text: "b" }]), false);
  assert.equal(hasValidCriterionIds([{ id: " ", text: "a" }]), false);
});

test("deliverable URLs follow the contract: https, public domain, default port, no fragment", () => {
  assert.equal(validateDeliveryUrl("https://example.org/work"), null);
  assert.equal(validateDeliveryUrl("https://example.org:443/work"), null);
  assert.equal(validateDeliveryUrl("https://example.org/a?b=1"), null);
  assert.ok(validateDeliveryUrl(""));
  assert.match(validateDeliveryUrl("http://example.org")!, /https/);
  assert.ok(validateDeliveryUrl("ftp://example.org"));
  assert.ok(validateDeliveryUrl("javascript:alert(1)"));
  assert.ok(validateDeliveryUrl("https://user:pw@example.org"));
  assert.ok(validateDeliveryUrl("https://localhost/x"));
  assert.ok(validateDeliveryUrl("https://192.168.0.1/x"));
  assert.ok(validateDeliveryUrl("https://8.8.8.8/x"));
  assert.ok(validateDeliveryUrl("https://printer.local/x"));
  assert.ok(validateDeliveryUrl("https://intranet/x"));
  assert.ok(validateDeliveryUrl("https://exa mple.org"));
  assert.match(validateDeliveryUrl("https://example.org/x#top")!, /fragment/);
  assert.match(validateDeliveryUrl("https://example.org:8443/x")!, /default https port/);
  assert.ok(validateDeliveryUrl("https://site.test/x"), "reserved top-level domain");
  assert.match(validateDeliveryUrl("https://example.org/" + "a".repeat(2048))!, /at most 2048/);
  assert.equal(validateDeliveryUrl("https://example.org/" + "a".repeat(2000)), null);
});

test("criterion ids follow the contract up to C20, C10 included", () => {
  const c = buildCriteria(Array.from({ length: 20 }, (_, i) => `Criterion number ${i + 1}`));
  assert.equal(c[9]!.id, "C10");
  assert.equal(c[19]!.id, "C20");
  assert.equal(hasValidCriterionIds(c), true);
});
